def main():
 p=argparse.ArgumentParser();p.add_argument("--output",type=Path,required=True);a=p.parse_args();param=load(a.output/"checkpoint_parameter_state.json");init=load(a.output/"checkpoint_vs_initialization.json");mask=load(a.output/"mask_survival_audit.json");hook=load(a.output/"hook_execution_audit.json");grad=load(a.output/"single_batch_gradient_audit.json");step=load(a.output/"one_step_update_audit.json");traj=load(a.output/"diagnostic_50step_trajectory.json");amp=load(a.output/"amp_skip_audit.json");arm=load(a.output/"stage9a_effective_arm_reinterpretation.json")
 projection_zero=all(param[c]["projection_weights_and_biases_exact_zero"] for c in ("short","pinhole"));entire_unchanged=all(init[c]["all_exact_equal"] for c in ("short","pinhole"));nonfinite_gradient=any(grad[c]["status"]=="NONFINITE_GRADIENT" for c in ("short","pinhole"));gradient_reaches=all(grad[c]["status"]=="GRADIENT_REACHES_PROJECTION" for c in ("short","pinhole"));one_step_works=all(step[c].get("post_step_parameters_finite",False) and step[c]["projection_weight_changed"] and not step[c]["post_step_output_still_exact_zero"] for c in ("short","pinhole"));save_load_ok=all(step[c]["state_dict_roundtrip_exact_equal"] for c in ("short","pinhole"));mask_collapse=mask["status"]=="MASK_DOWNSAMPLE_COLLAPSE_SUPPORTED";hooks_ok=all(hook[c][v]["hook_called_count"]==2 and all(x["condition_set_before_hook"] for x in hook[c][v]["calls"]) for c in ("short","pinhole") for v in ("fresh","trained"));trajectory_updates=traj.get("successful_updates",0)>0;amp_collapse=amp["status"] in ("AMP_SCALE_COLLAPSED_TO_ZERO","ALL_UPDATES_SKIPPED_NONFINITE")
 causes=[]
 if nonfinite_gradient and amp_collapse:causes.append("NONFINITE_GRADIENT_AMP_SCALE_COLLAPSE")
