 status="MULTIPLE_IMPLEMENTATION_FAILURES" if len(causes)>1 else causes[0] if causes else "NO_CLEAR_DEAD_ADAPTER_CAUSE";doc={"status":status,"evidence":{"formal_projection_state_exact_zero":projection_zero,"entire_formal_adapter_matches_fresh_initialization":entire_unchanged,"fresh_nonfinite_gradient":nonfinite_gradient,"fresh_gradient_reaches_projection":gradient_reaches,"fresh_one_step_makes_finite_nonzero_residual":one_step_works,"diagnostic_successful_updates":traj.get("successful_updates",0),"diagnostic_parameters_update":trajectory_updates,"diagnostic_stopped_on_zero_scale":traj.get("stopped_on_zero_scale",False),"mask_support_collapse":mask_collapse,"hooks_and_conditions_execute":hooks_ok,"state_dict_roundtrip_preserves_values_including_nan":save_load_ok,"amp_skip_status":amp["status"]},"contributing_statuses":causes,"UNADAPTED_PRETRAINED_BACKBONE_INSUFFICIENT":True,"FULL_UNET_FINETUNING_REQUIRED":False,"LORA_REQUIRED":False,"historical_stage9a_stage9c_modified":False,"detector_training_count":0,"official_validation_use_count":0};save(a.output/"stage9d_status.json",doc)
 lines=["# DeepPCB Stage9D Dead Adapter Root-Cause Audit","",f"Status: **{status}**.","","## Decision evidence",""]+[f"- {k}: {v}" for k,v in doc["evidence"].items()]+["","The Stage9A arm remains formally failed and is reinterpreted as an unadapted pretrained-backbone control because its learned residual path was inactive.","UNADAPTED_PRETRAINED_BACKBONE_INSUFFICIENT=true, but neither full-UNet fine-tuning nor LoRA is declared required: the lightweight path never received a valid empirical test.","VAE_BOTTLENECK_NOT_SUPPORTED remains frozen from Stage9C. All subsequent fidelity work must use the Stage7B/8B adaptive padded crop protocol.","","No detector, formal 2,000-step model, new architecture, LoRA, or official-validation experiment was run."];(a.output/"STAGE9D_REPORT.md").write_text("\n".join(lines)+"\n");print(json.dumps(doc,indent=2))
